using System;using System.Collections.Generic;using System.IO;using UnityEngine;using UnityEditor;
public static class DrpgPhase5DiagnosticTests {
 public static string Run(){var lines=new List<string>();Action<bool,string> check=(ok,text)=>lines.Add((ok?"PASS ":"FAIL ")+text);var p=new PlacedEnemyDefinition{id="phase5.check",cell=new Vector2Int(1,1),exploration=new EnemyExplorationSettings{profile=EnemyExplorationProfile.Patrol}};var rows=new[]{"#######","#..#..#","#..#..#","#######"};Func<List<string>> errors=()=>{var list=new List<string>();EnemyExplorationSettings.Validate(p,rows,list);return list;};
 check(errors().Exists(e=>e.Contains("necesita una ruta")),"Empty Patrol route detected");p.exploration.patrol=new[]{new Vector2Int(3,1)};check(errors().Exists(e=>e.Contains("fuera del suelo")),"Waypoint on wall detected");p.exploration.patrol=new[]{new Vector2Int(5,1)};check(errors().Exists(e=>e.Contains("inalcanzable")),"Disconnected waypoint detected");p.exploration.patrol=new[]{new Vector2Int(2,1)};check(errors().Count==0,"Valid connected patrol accepted");p.exploration.detectionSteps=-1;check(errors().Exists(e=>e.Contains("parametros")),"Negative detection detected");p.exploration.detectionSteps=2;p.exploration.respawnSeconds=float.NaN;check(errors().Exists(e=>e.Contains("parametros")),"NaN respawn detected");p.exploration.respawnSeconds=0;p.unique=true;p.exploration.persistence=EnemyExplorationPersistence.ResetOnReentry;check(errors().Exists(e=>e.Contains("Unique/Boss")),"Unique reset contradiction detected");p.unique=false;p.category=PlacedEnemyCategory.Boss;p.exploration.persistence=EnemyExplorationPersistence.TimedRespawn;check(errors().Exists(e=>e.Contains("Unique/Boss")),"Boss respawn contradiction detected");
 var main=DungeonMapSettings.Current;var regions=main.regions!=null?main.regions:DungeonRegionSettings.Current;var diagnostic=DungeonMapDiagnostics.Analyze(main);check(diagnostic.errors.Count==0,"Phase 1 main dungeon diagnostic remains valid");check(Array.TrueForAll(regions.placedEnemies,e=>e.exploration==null||e.exploration.profile==EnemyExplorationProfile.Legacy),"All published placements remain Legacy");check(Array.Exists(regions.placedEnemies,e=>e.speciesId=="Makong"&&e.holdPosition&&e.unique),"Makong remains static and unique");
 foreach(string name in new[]{"FloorA","FloorB"}){var map=Resources.Load<DungeonMapSettings>("DrpgPhase5Tests/"+name);check(map!=null&&DungeonMapDiagnostics.Analyze(map).errors.Count==0,"Independent fixture "+name+" passes consolidated diagnostic");}
 var so=new SerializedObject(regions);var elements=so.FindProperty("placedEnemies");check(elements.arraySize>0&&elements.GetArrayElementAtIndex(0).FindPropertyRelative("exploration").FindPropertyRelative("patrol")!=null,"Inspector exposes nested exploration and patrol configuration");
 var data=new DungeonSaveData();data.enemies.Add(new EnemyInstanceRecord{placementId=regions.placedEnemies[0].id,defeated=true,currentHP=0});DungeonMapPersistence.ResetExplorationOnReentry(data,main);check(data.enemies[0].defeated,"Legacy main-map region binding preserves existing defeats");
 Directory.CreateDirectory("Tests");File.WriteAllLines("Tests/DrpgPhase5Diagnostics.txt",lines);return string.Join("\n",lines.ToArray());
 }
}
